*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{width:100%;height:100%;overflow:hidden;background:#0b0d16}
body{font-family:'Press Start 2P',ui-monospace,Menlo,Consolas,monospace;color:#e8e4d4;
  -webkit-user-select:none;user-select:none;touch-action:none;overscroll-behavior:none}
#cv{position:fixed;inset:0;width:100%;height:100%;display:block;image-rendering:pixelated;image-rendering:crisp-edges}
#uiRoot{position:fixed;inset:0;pointer-events:none;overflow:hidden}
#uiRoot>*{pointer-events:none}
.hidden{display:none!important}
.shown{display:flex!important}
#boot{position:fixed;inset:0;z-index:99;background:#0b0d16;flex-direction:column;gap:14px;
  align-items:center;justify-content:center;color:#f2b04a;font-size:18px;letter-spacing:2px}
#boot span{color:#6b7488;font-size:8px;letter-spacing:1px}
/* panels & buttons */
.panel{background:rgba(16,19,32,.92);box-shadow:0 0 0 2px #05070d,inset 0 0 0 2px #3c4a63;
  border:2px solid #10141f;border-radius:4px}
.pbtn{pointer-events:auto;display:inline-flex;align-items:center;justify-content:center;gap:8px;
  font:inherit;color:#e8e4d4;background:#242c44;padding:10px 14px;cursor:pointer;
  border:2px solid #10141f;border-radius:4px;box-shadow:0 0 0 2px #05070d,inset 0 0 0 2px #465273;
  text-shadow:1px 1px 0 #000;transition:transform .04s}
.pbtn:hover,.pbtn.sel{background:#313c5e;box-shadow:0 0 0 2px #05070d,inset 0 0 0 2px #6f80ab;color:#ffd97a}
.pbtn:active,.pbtn.press{transform:translateY(2px)}
.pbtn[disabled]{opacity:.45;pointer-events:none}
.pbtn.danger:hover{background:#5a2430;box-shadow:0 0 0 2px #05070d,inset 0 0 0 2px #a35;color:#ff9d9d}
/* bars */
.bar{position:relative;height:10px;background:#05070d;border:2px solid #10141f;border-radius:3px;overflow:hidden}
.bar i{position:absolute;inset:0;width:50%;transition:width .15s}
.bar span{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;
  font-size:7px;color:#fff;text-shadow:1px 1px 0 #000}
/* toasts */
#toasts{position:absolute;top:64px;left:50%;transform:translateX(-50%);display:flex;flex-direction:column;
  gap:6px;align-items:center;pointer-events:none;z-index:30}
.toast{background:rgba(12,15,26,.95);color:#ffe9b0;font-size:8px;padding:8px 12px;border-radius:4px;
  border:2px solid #10141f;box-shadow:0 0 0 2px #05070d,inset 0 0 0 2px #465273;
  animation:tin .25s ease-out;text-shadow:1px 1px 0 #000;max-width:76vw;text-align:center;line-height:1.6}
.toast.gold{color:#ffd97a}
@keyframes tin{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:none}}
.toast.out{opacity:0;transition:opacity .5s}
/* vignette & storm */
#vin{position:absolute;inset:0;box-shadow:inset 0 0 120px rgba(0,0,10,.55);pointer-events:none}
#vin.hurt{box-shadow:inset 0 0 140px rgba(160,20,30,.75)}
#storm{position:absolute;inset:0;opacity:0;background:radial-gradient(ellipse at 50% 40%,rgba(200,160,90,.08),rgba(120,90,40,.22));
  pointer-events:none;transition:opacity .8s}

/* HUD */
#hud{position:absolute;top:0;left:0;right:0;display:flex;justify-content:space-between;align-items:flex-start;padding:8px;gap:8px;z-index:10}
#hudL{display:flex;flex-direction:column;gap:5px;min-width:150px}
#namePlate{display:flex;align-items:baseline;gap:8px;font-size:9px;color:#ffd97a;text-shadow:1px 1px 0 #000}
#namePlate small{font-size:7px;color:#9fb0d8}
.bar.hp{width:150px}.bar.hp i{background:linear-gradient(#ff7a6b,#c0392b)}
.bar.xp{width:150px;height:6px}.bar.xp i{background:linear-gradient(#7ee0ff,#2a7fb8)}
#coinRow{display:flex;gap:10px;align-items:center;font-size:8px;color:#ffe9b0;text-shadow:1px 1px 0 #000}
#coinRow canvas{width:14px;height:14px;image-rendering:pixelated}
#coinRow b{min-width:16px}
#hudR{display:flex;flex-direction:column;align-items:flex-end;gap:5px;max-width:46vw}
#chapterTag{font-size:7px;color:#ffd97a;padding:7px 9px;line-height:1.5;text-align:right}
#questTracker{font-size:7px;color:#cfe3ff;padding:7px 9px;max-width:170px;line-height:1.6;text-align:right}
#questTracker b{color:#8fe08f;display:block}
#miniWrap{position:relative}
#mini{display:block;width:132px;height:99px;image-rendering:pixelated;border-radius:4px}
#hudShards{font-size:7px;color:#9fe8ff;text-shadow:1px 1px 0 #000;display:flex;align-items:center;gap:6px}
#hudShards canvas{width:12px;height:12px;image-rendering:pixelated}
/* boss bar */
#bossWrap{position:absolute;top:8px;left:50%;transform:translateX(-50%);text-align:center;z-index:12}
#bossName{font-size:8px;color:#ffb3a1;text-shadow:1px 1px 0 #000;margin-bottom:4px;letter-spacing:1px}
#bossBar{width:min(420px,60vw);height:10px;background:#05070d;border:2px solid #10141f;border-radius:3px;overflow:hidden;box-shadow:0 0 0 2px #05070d}
#bossFill{height:100%;width:100%;background:linear-gradient(#ff5d7e,#8e1b3f);transition:width .12s}
@media (max-width:640px){
  #hudL{min-width:120px}.bar.hp{width:118px}.bar.xp{width:118px}
  #chapterTag{max-width:34vw}#questTracker{max-width:34vw;font-size:6px}
  #mini{width:96px;height:72px}
}

/* Dialogue */
#dlg{position:absolute;left:0;right:0;bottom:0;display:flex;justify-content:center;padding:0 10px 14px;z-index:40}
#dlgBox{width:min(660px,94vw);pointer-events:auto;padding:12px 14px 10px;position:relative}
#dlgName{position:absolute;top:-12px;left:10px;background:#242c44;padding:4px 10px;font-size:8px;color:#ffd97a;
  border:2px solid #10141f;border-radius:4px;box-shadow:0 0 0 2px #05070d,inset 0 0 0 2px #465273}
#dlgText{font-size:9px;line-height:1.9;min-height:52px;color:#efe9d8;text-shadow:1px 1px 0 #000;white-space:pre-wrap}
#dlgText .em{color:#ffd97a}
#dlgChoices{display:flex;flex-direction:column;gap:5px;margin-top:9px}
#dlgChoices .pbtn{font-size:8px;justify-content:flex-start;padding:8px 10px;text-align:left;line-height:1.5}
#dlgChoices .pbtn.sel::before{content:'›';margin-right:6px;color:#ffd97a}
#dlgHint{position:absolute;right:10px;bottom:6px;font-size:8px;color:#6f80ab;animation:blink 1s steps(2) infinite}
@keyframes blink{50%{opacity:.15}}

/* Chapter cards, endings, big overlays */
#card{position:absolute;inset:0;z-index:60;display:flex;flex-direction:column;align-items:center;justify-content:center;
  background:rgba(5,7,13,.82);text-align:center;padding:20px;gap:16px}
#card .cnum{font-size:10px;color:#9fb0d8;letter-spacing:3px}
#card .ctitle{font-size:clamp(16px,5vw,30px);color:#ffd97a;text-shadow:0 3px 0 #3a2405,0 0 24px rgba(255,180,60,.35);line-height:1.7}
#card .csub{font-size:8px;color:#8a97b8;max-width:70vw;line-height:2}
#card .rule{width:120px;height:3px;background:#ffd97a;box-shadow:0 0 12px rgba(255,180,60,.6)}
/* endings */
#endScr{position:absolute;inset:0;z-index:70;display:flex;align-items:center;justify-content:center;padding:16px;background:rgba(4,6,11,.94)}
#endInner{width:min(640px,94vw);max-height:92vh;overflow:auto;padding:22px 20px;display:flex;flex-direction:column;gap:14px;align-items:center;text-align:center}
#endKind{font-size:8px;letter-spacing:2px;color:#9fb0d8}
#endTitle{font-size:clamp(15px,4.6vw,24px);line-height:1.7;text-shadow:0 2px 0 #000}
#endTitle.bad{color:#ff9d8f}#endTitle.good{color:#aef2b0}#endTitle.secret{color:#cfa9ff}
#endBody{font-size:9px;line-height:2.1;color:#e8e4d4;white-space:pre-wrap}
#endFoot{font-size:8px;color:#ffd97a}
/* title */
#titleScr{position:absolute;inset:0;z-index:65;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px}
#tLogo{font-size:clamp(22px,7vw,44px);color:#f2b04a;letter-spacing:4px;text-shadow:0 4px 0 #57220a,0 0 30px rgba(242,176,74,.35);line-height:1.6}
#tSub{font-size:9px;color:#9fb0d8;letter-spacing:2px}
#tMenu{display:flex;flex-direction:column;gap:9px;margin-top:18px;width:min(320px,84vw)}
#tMenu .pbtn{font-size:9px}
#tFoot{position:absolute;bottom:10px;font-size:7px;color:#5b6residual}
#tFoot{font-size:7px;color:#5b6880}

