input.content:
/* Pause / inventory / quests / shop / map overlays */
#menuScr{position:absolute;inset:0;z-index:50;display:flex;align-items:center;justify-content:center;background:rgba(4,6,11,.72);pointer-events:auto}
#menuBox{width:min(760px,96vw);max-height:92vh;display:flex;flex-direction:column;gap:10px;padding:14px}
#menuTabs{display:flex;gap:6px;flex-wrap:wrap}
#menuTabs .pbtn{font-size:8px;padding:8px 10px}
#menuBody{flex:1;overflow:auto;min-height:180px;max-height:60vh;display:flex;gap:12px}
#menuFoot{display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap}
.sec{font-size:8px;color:#ffd97a;letter-spacing:1px;margin:10px 0 6px}
.row{display:flex;align-items:center;gap:10px;padding:7px 8px;border-radius:4px;font-size:8px;line-height:1.6;
  background:rgba(255,255,255,.03);border:2px solid transparent}
.row.sel{border-color:#6f80ab;background:rgba(110,140,200,.12)}
.row canvas{width:20px;height:20px;image-rendering:pixelated;flex:none}
.row .grow{flex:1;min-width:0}
.row .mut{color:#8a97b8;font-size:7px}
.row .eq{color:#8fe08f}
.col{flex:1;min-width:260px;display:flex;flex-direction:column;gap:5px}
.col.side{max-width:210px;font-size:7px;line-height:1.9;color:#9fb0d8}
.side b{color:#ffd97a}
.kv{display:flex;justify-content:space-between;gap:8px;font-size:8px}
.kv b{color:#ffe9b0}
.list{display:flex;flex-direction:column;gap:5px}
#mapCv{width:min(560px,88vw);height:auto;image-rendering:pixelated;border-radius:4px;background:#0a0c14}
.hintline{font-size:7px;color:#8a97b8;line-height:1.8;margin-top:8px}
input.txt{font:inherit;font-size:10px;color:#ffd97a;background:#10141f;border:2px solid #10141f;border-radius:4px;
  box-shadow:inset 0 0 0 2px #465273;padding:9px 10px;outline:none;pointer-events:auto;width:100%}
.tog{min-width:150px}

/* Touch controls */
#touch{position:absolute;inset:0;z-index:20;pointer-events:none}
#stickZone{position:absolute;left:0;bottom:0;width:44%;height:60%;pointer-events:auto}
#stickN{position:absolute;width:74px;height:74px;margin:-37px;border-radius:50%;
  background:rgba(30,38,60,.35);border:2px solid rgba(140,160,200,.4);display:none}
#stickN i{position:absolute;left:50%;top:50%;width:30px;height:30px;margin:-15px;border-radius:50%;
  background:rgba(200,215,255,.5);border:2px solid rgba(240,245,255,.6)}
#btnsR{position:absolute;right:10px;bottom:16px;display:flex;align-items:flex-end;gap:10px;pointer-events:auto}
#btnsTop{position:absolute;right:10px;top:150px;display:flex;flex-direction:column;gap:8px;pointer-events:auto}
.tbtn{width:62px;height:62px;border-radius:50%;font:inherit;font-size:10px;color:#e8e4d4;
  background:rgba(36,44,68,.8);border:2px solid #10141f;box-shadow:0 0 0 2px #05070d,inset 0 0 0 2px #465273;
  display:flex;align-items:center;justify-content:center;flex-direction:column;gap:2px;cursor:pointer}
.tbtn small{font-size:6px;color:#9fb0d8}
.tbtn:active,.tbtn.press{transform:scale(.94);background:rgba(70,84,130,.9)}
.tbtn.big{width:74px;height:74px;background:rgba(58,42,48,.85)}
.tbtn.useb{background:rgba(36,60,50,.85)}
.tbtn.potb{width:48px;height:48px;font-size:8px}
.tbtn.menb{width:44px;height:44px;font-size:8px}
#potBadge{position:absolute;top:-4px;right:-4px;background:#ffd97a;color:#3a2405;font-size:7px;padding:2px 4px;border-radius:6px;border:1px solid #57220a}
@media (max-height:420px){
  .tbtn{width:52px;height:52px;font-size:9px}.tbtn.big{width:62px;height:62px}
  #btnsTop{top:auto;bottom:110px;right:auto;left:10px;flex-direction:row}
}

'use strict';
/* ===== EMBERFALL core utils ===== */
const TILE = 16, TAU = Math.PI * 2;
const V = { zoom: 3, w: 0, h: 0 };
const U = {
  clamp(v, a, b) { return v < a ? a : v > b ? b : v; },
  lerp(a, b, t) { return a + (b - a) * t; },
  dist(ax, ay, bx, by) { const x = bx - ax, y = by - ay; return Math.sqrt(x * x + y * y); },
  d2(ax, ay, bx, by) { const x = bx - ax, y = by - ay; return x * x + y * y; },
  ang(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax); },
  angDiff(a, b) { let d = (b - a) % TAU; if (d > Math.PI) d -= TAU; if (d < -Math.PI) d += TAU; return d; },
  // deterministic RNG
  rng(seed) { let s = seed >>> 0; return function () { s = (s + 0x6D2B79F5) >>> 0; let t = s; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; },
  ri(r, a, b) { return a + Math.floor(r() * (b - a + 1)); },
  pick(r, arr) { return arr[Math.floor(r() * arr.length)]; },
  chance(p) { return Math.random() < p; },
  irnd(a, b) { return a + Math.floor(Math.random() * (b - a + 1)); },
  hash(x, y, s) { let h = (x | 0) * 374761393 + (y | 0) * 668265263 + (s | 0) * 947430521; h = Math.imul(h ^ (h >>> 13), 1274126177); h ^= h >>> 16; return (h >>> 0) / 4294967296; },
  smooth(t) { return t * t * (3 - 2 * t); },
  noise2(x, y, s) { const xi = Math.floor(x), yi = Math.floor(y), tx = this.smooth(x - xi), ty = this.smooth(y - yi);
    const a = this.hash(xi, yi, s), b = this.hash(xi + 1, yi, s), c = this.hash(xi, yi + 1, s), d = this.hash(xi + 1, yi + 1, s);
    return this.lerp(this.lerp(a, b, tx), this.lerp(c, d, tx), ty); },
  fbm(x, y, s, oct = 3, sc = 0.045) { let v = 0, amp = 0.55, f = 1, tot = 0; for (let i = 0; i < oct; i++) { v += this.noise2(x * f * sc, y * f * sc, s + i * 77) * amp; tot += amp; amp *= 0.55; f *= 2.1; } return v / tot; },
};
const $ = id => document.getElementById(id);
function el(tag, cls, html) { const e = document.createElement(tag); if (cls) e.className = cls; if (html != null) e.innerHTML = html; return e; }
function cnv(w, h) { const c = document.createElement('canvas'); c.width = w; c.height = h; return c; }
function px(g, x, y, c, w = 1, h = 1) { g.fillStyle = c; g.fillRect(x, y, w, h); }
function hex2(h) { return h; }
function shade(hex, amt) { // hex '#rrggbb', amt -1..1
  const n = parseInt(hex.slice(1), 16); let r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  if (amt >= 0) { r += (255 - r) * amt; g += (255 - g) * amt; b += (255 - b) * amt; } else { r *= (1 + amt); g *= (1 + amt); b *= (1 + amt); }
  return 'rgb(' + (r | 0) + ',' + (g | 0) + ',' + (b | 0) + ')';
}
const PAL = {
  out: '#05070d', ink: '#10141f', panel: '#242c44', panel2: '#313c5e', line: '#465273', gold: '#ffd97a', gold2: '#f2b04a',
  skin: '#e8b796', skin2: '#d99f78', hairD: '#4a3226', hairL: '#8a5a33', clothB: '#3a5f8a', clothG: '#4f8a4f',
  clothR: '#a33b3b', clothP: '#6a4a8a', clothY: '#c9a04a', clothK: '#2b3040', bone: '#e8e4d4', blood: '#c0392b',
  leaf1: '#2e6b3a', leaf2: '#3f8f4a', leaf3: '#57a85f', grass1: '#3f8f4a', grass2: '#357a40', grass3: '#4aa355',
  dirt1: '#8a6a42', dirt2: '#6f5433', sand1: '#d9c37e', sand2: '#c4a95e', water1: '#2a5f8a', water2: '#1f4a6e',
  rock1: '#6f7585', rock2: '#4a4f5e', cave1: '#2b3040', cave2: '#3a4155', wood1: '#8a6a42', wood2: '#5e4629',
  roof1: '#a33b3b', roof2: '#7a2d2d', ember: '#f2b04a', ember2: '#c95a1e', spark: '#ffe9b0',
};
const G = { // mutable game state
  mode: 'boot', panel: null, mapKey: 'world', mapObj: null, time: 0, clock: 120, // clock = minutes in day cycle
  flags: {}, quests: {}, hope: 0, shards: 0, chapter: 0, playtime: 0,
  p: null, mobs: [], projs: [], parts: [], texts: [], drops: [], decos: [], focus: null,
  cam: { x: 0, y: 0, sx: 0, sy: 0, shake: 0 }, opened: {}, gates: {}, triggers: {},
  reveals: {}, hitstop: 0, boss: null, spawnPt: null, pendingSave: false, lastSaveName: 'Emberfall',
};
function F(k, v) { if (v !== undefined) { G.flags[k] = v; } return G.flags[k] || 0; }
function got(k) { return !!G.flags[k]; }
function addHope(n, why) { if (n > 0 && G.hope >= 6) return; G.hope = U.clamp(G.hope + n, 0, 6); if (why) toast('Hope rises · ' + why, 1); }

'use strict';
/* ===== save system ===== */
const SAVE_KEY = 'emberfall_save1', META_KEY = 'emberfall_meta1';
const Settings = { sfx: true, music: true, autosave: true };
function loadMeta() {
  try { const m = JSON.parse(localStorage.getItem(META_KEY) || '{}'); META.endings = m.endings || {}; META.seen = m.seen || {}; Object.assign(Settings, m.settings || {}); } catch (e) { }
}
function saveMeta() { try { localStorage.setItem(META_KEY, JSON.stringify({ endings: META.endings, seen: META.seen, settings: Settings })); } catch (e) { } }
const META = { endings: {}, seen: {}, load: loadMeta, save: saveMeta };
function b64(u8) { let s = ''; for (let i = 0; i < u8.length; i++) s += String.fromCharCode(u8[i]); return btoa(s); }
function unb64(str) { const s = atob(str), u = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i); return u; }
function snapshot() {
  const p = G.p, r = {};
  r.v = 3; r.map = G.mapKey; r.x = Math.round(p.x); r.y = Math.round(p.y); r.face = p.face;
  r.lvl = p.lvl; r.xp = p.xp; r.hp = Math.round(p.hp); r.coins = p.coins; r.playtime = Math.round(G.playtime);
  r.clock = G.clock; r.origin = F('origin'); r.name = p.name;
  r.inv = JSON.stringify(p.inv); r.wpn = p.wpn; r.arm = p.arm; r.acc = p.acc;
  r.own = JSON.stringify({ w: p.ownW, a: p.ownA, c: p.ownC });
  r.flags = JSON.stringify(G.flags); r.quests = JSON.stringify(G.quests);
  r.hope = G.hope; r.shards = G.shards; r.chapter = G.chapter; r.opened = JSON.stringify(G.opened);
  r.gates = JSON.stringify(G.gates); r.trig = JSON.stringify(G.triggers); r.spawn = JSON.stringify(G.spawnPt);
  r.rev = {}; for (const k in G.reveals) r.rev[k] = b64(G.reveals[k]);
  return r;
}
function saveGame(silent) {
  try { localStorage.setItem(SAVE_KEY, JSON.stringify(snapshot())); if (!silent) toast('Journey saved', 1); } catch (e) { toast('Save failed', 0); }
}
function hasSave() { try { return !!localStorage.getItem(SAVE_KEY); } catch (e) { return false; } }
function wipeSave() { try { localStorage.removeItem(SAVE_KEY); } catch (e) { } }
function loadInto() {
  let r; try { r = JSON.parse(localStorage.getItem(SAVE_KEY) || 'null'); } catch (e) { return false; }
  if (!r || r.v !== 3) return false;
  G.flags = JSON.parse(r.flags); G.quests = JSON.parse(r.quests); G.opened = JSON.parse(r.opened);
  G.gates = JSON.parse(r.gates); G.triggers = JSON.parse(r.trig); G.spawnPt = JSON.parse(r.spawn);
  G.hope = r.hope; G.shards = r.shards; G.chapter = r.chapter; G.playtime = r.playtime || 0; G.clock = r.clock;
  makePlayer(r.x, r.y, r.face, r.lvl, r.xp, r.hp, r.coins);
