'use strict';
/* ===== mob & boss definitions ===== */
/* ai: chase | hopper | flutter | lunge | archer | shooter | slam | boss */
const MOBS = {
  slime: { n: 'Bog Slime', hp: 12, dmg: 4, xp: 5, coin: [2, 5], spd: 26, ai: 'hopper', r: 6, spr: 'slime', drops: [['pot_s', .1]] },
  bat: { n: 'Ash Bat', hp: 9, dmg: 3, xp: 6, coin: [1, 4], spd: 52, ai: 'flutter', r: 5, spr: 'bat' },
  wolf: { n: 'Grove Wolf', hp: 16, dmg: 6, xp: 9, coin: [2, 6], spd: 40, ai: 'lunge', r: 6, spr: 'wolf', drops: [['pot_s', .08]] },
  scorp: { n: 'Dune Scorpion', hp: 15, dmg: 6, xp: 9, coin: [2, 7], spd: 30, ai: 'chase', r: 6, spr: 'scorp' },
  bandit: { n: 'Toll Bandit', hp: 24, dmg: 8, xp: 15, coin: [8, 16], spd: 38, ai: 'archer', r: 6, spr: 'bandit', proj: 'arrow', drops: [['pot_s', .2]] },
  crawler: { n: 'Barrow Crawler', hp: 20, dmg: 7, xp: 13, coin: [3, 9], spd: 36, ai: 'chase', r: 6, spr: 'crawler', drops: [['emberstone', .25]] },
  golem: { n: 'Cave Golem', hp: 40, dmg: 12, xp: 24, coin: [10, 20], spd: 22, ai: 'slam', r: 8, spr: 'golem', drops: [['emberstone', .5], ['pot_l', .15]] },
  wraith: { n: 'Dust Wraith', hp: 26, dmg: 9, xp: 17, coin: [6, 14], spd: 34, ai: 'shooter', r: 6, spr: 'wraith', proj: 'bolt' },
  guard: { n: 'Keep Sentry', hp: 34, dmg: 11, xp: 22, coin: [9, 18], spd: 44, ai: 'lunge', r: 6, spr: 'guard', drops: [['pot_l', .2]] },
};
const BOSSES = {
  warden: { n: 'THE BRAMBLE WARDEN', hp: 110, dmg: 10, xp: 130, spd: 30, r: 12, spr: 'warden', arena: 26 },
  sovereign: { n: 'THE DUNE SOVEREIGN', hp: 170, dmg: 14, xp: 200, spd: 46, r: 12, spr: 'sovereign', arena: 30 },
  deepking: { n: 'THE HOLLOW KING', hp: 240, dmg: 16, xp: 260, spd: 34, r: 13, spr: 'deepking', arena: 30 },
  marshal: { n: 'WRAITH MARSHAL', hp: 320, dmg: 18, xp: 340, spd: 52, r: 12, spr: 'marshal', arena: 32 },
};
/* ==== spawning zones are set by worldgen ==== */
function xpNeed(lvl) { return 25 + 22 * (lvl - 1) + (lvl - 1) * (lvl - 1) * 7; }
function playerAtk() {
  const p = G.p; let a = 2 + p.lvl + (WPN[p.wpn] ? WPN[p.wpn].atk : 0) + G.shards * 2;
  if (F('origin') === 'valor') a += 2; if (F('elixirT') > 0) a = Math.round(a * 1.15); return a;
}
function playerDef() { const p = G.p; return (ARM[p.arm] ? ARM[p.arm].def : 0); }
function playerCrit() { let c = .07 + (G.p.acc === 'ring' ? .08 : 0); if (F('origin') === 'wits') c += .05; return c; }
function playerSpd() { return 74 * (F('origin') === 'wits' ? 1.12 : 1); }
function healPlayer(n) { const p = G.p; const before = p.hp; p.hp = Math.min(p.maxhp, p.hp + n); if (p.hp > before) { floatText(p.x, p.y - 14, '+' + Math.round(p.hp - before), '#8fe08f'); burst(p.x, p.y, '#8fe08f', 6); } }
function hurtPlayer(dmg, kx, ky) {
  const p = G.p; if (p.inv > 0 || G.mode !== 'play') return;
  const d = Math.max(1, Math.round(dmg - playerDef() * .55));
  p.hp -= d; p.inv = .8; p.kx = (kx || 0); p.ky = (ky || 0);
  G.cam.shake = Math.min(8, 3 + d * .2); SFX.play('hurt'); vibrate(40);
  floatText(p.x, p.y - 16, '-' + d, '#ff7a6b'); burst(p.x, p.y, '#ff5d5d', 8);
  const v = $('vin'); v.classList.add('hurt'); setTimeout(() => v.classList.remove('hurt'), 250);
  if (p.hp <= 0) playerDie();
}
function vibrate(ms) { if (Settings.vib !== false && navigator.vibrate) { try { navigator.vibrate(ms); } catch (e) { } } }
function makePlayer(x, y, face, lvl, xp, hp, coins) {
  const maxhp = 24 + 6 * ((lvl || 1) - 1) + (F('origin') === 'vigor' ? 16 : F('origin') ? 6 : 0);
  G.p = { x, y, vx: 0, vy: 0, face: face || 0, anim: 0, walkT: 0, atkT: 0, atkCd: 0, rollT: 0, rollCd: 0, inv: 0, hp, maxhp,
    lvl: lvl || 1, xp: xp || 0, coins: coins || 0, wpn: 'rusty', arm: 'cloth', acc: null, ownW: ['rusty'], ownA: ['cloth'], ownC: [],
    inv: { pot_s: 2 }, kx: 0, ky: 0, name: 'Ashe' };
  if (hp == null) G.p.hp = maxhp;
}

'use strict';
/* ===== quests, endings DB ===== */
const DLG = {}; // dialogue registry (filled by dlg_*.js)
const QDB = {
  dawn: { n: 'A Cold Kiln', steps: ['Wake and speak with Mara at the kiln.', 'Take the Rusty Blade she offers.'] },
  ch1: { n: 'The Wilting Grove', steps: ['Find the Warden\'s Mound in the Whisperwood, west.', 'End the Bramble Warden\'s blight — or spare it.'] },
  ch2: { n: 'Sand & Starlight', steps: ['Cross east to the Ashen Dunes.', 'Reach the Sunken Temple and face the Dune Sovereign.'] },
  ch3: { n: 'The Hollow Below', steps: ['Enter the Barrow Cave in the Emberrise mountains, north-west.', 'Descend to the Deep Hollow. Face the Hollow King.'] },
  ch4: { n: 'The Ember Keep', steps: ['Take the Ember Sigil to the Keep gate, north-east.', 'Climb to the throne. Face the Wraith Marshal.'] },
  fin: { n: 'The Ember Heart', steps: ['Enter the Heart chamber behind the throne.'] },
  q_tea: { n: 'Petalfall Tea', steps: ['Gather 3 Moonpetals from tall grass in the Whisperwood.', 'Bring them to Rowan.'] },
  q_lantern: { n: 'The Lost Lantern', steps: ['Find the child\'s lantern in the Barrow Cave.', 'Return it to Nima at the lake.'], key: 'childs_lantern' },
  q_remedy: { n: 'The Hermit\'s Remedy', steps: ['Gather 2 Red Pollen (dunes) and 1 Cave Moss (Barrow).', 'Bring them to Hesan at the oasis.'] },
  q_toll: { n: 'The Bandit\'s Toll', steps: ['Deal with the bandit at the crossroads.', 'Report to Mara, or keep the coin.'] },
  q_well: { n: 'A Wish in the Well', steps: ['Toss a coin for Pip\'s wish at the village well.'] },
  q_ghost: { n: 'The Last Word', steps: ['Speak with the pale spirit among the graves.'] },
};
function addQuest(id) { if (!G.quests[id]) { G.quests[id] = { s: 0, done: false }; toast('New quest: ' + QDB[id].n, 1); SFX.play('quest'); } }
function qStage(id) { const q = G.quests[id]; return q ? q.s : -1; }
function advanceQuest(id) { const q = G.quests[id]; if (!q || q.done) return; q.s++; if (q.s >= QDB[id].steps.length) completeQuest(id); else { toast(QDB[id].n + ': ' + QDB[id].steps[q.s]); SFX.play('quest'); } }
function completeQuest(id, silent) { const q = G.quests[id]; if (!q || q.done) return; q.done = true; if (!silent) { toast('Quest complete: ' + QDB[id].n, 1); SFX.play('quest'); } }
function questReward(id) {
  const R = { q_tea: { c: 30, hope: 1, items: { pot_s: 2 } }, q_lantern: { c: 40, hope: 1, acc: 'lantern' },
    q_remedy: { c: 50, hope: 1, acc: 'cloak' }, q_toll: { c: 20, hope: 1 }, q_well: { c: 0, hope: 0 }, q_ghost: { hope: 1 } }[id];
  if (!R) return; if (R.c) { G.p.coins += R.c; toast('+' + R.c + ' coins', 1); }
  if (R.acc && !G.p.ownC.includes(R.acc)) { G.p.ownC.push(R.acc); G.p.acc = G.p.acc || R.acc; toast('Charm: ' + ACC[R.acc].n, 1); SFX.play('chest'); }
  if (R.hope) addHope(R.hope);
}
const CHAPTERS = [
  { n: 'Prologue', t: 'THE COLD KILN' },
  { n: 'Chapter I', t: 'THE WILTING GROVE' },
  { n: 'Chapter II', t: 'SAND & STARLIGHT' },
  { n: 'Chapter III', t: 'THE HOLLOW BELOW' },
  { n: 'Chapter IV', t: 'THE EMBER KEEP' },
  { n: 'Finale', t: 'THE EMBER HEART' },
];
const ENDINGS = {
  ash: { kind: 'bad', t: 'ASH ADAM', txt: 'You pressed the warm stone into the Marshal\'s gray palm.\nThe legion bowed. The kiln went dark by morning.\nThey say a new king walks the ash roads now, wearing your face,\nand that no bird has sung since.' },
  crown: { kind: 'bad', t: 'THE HOLLOW CROWN', txt: 'The Ember fits the hand like it was always yours.\nPower first. People after. People never.\nThe crown they forge for you is beautiful, and empty, and cold,\nand every mirror in the Keep refuses to show your eyes.' },
  dark: { kind: 'bad', t: 'THE LONG DARK', txt: 'You feed the Hollow, and the Hollow is grateful.\nGrateful things do not let go.\nDeep beneath the lake, a small warm light learns to breathe alone —\nand the world above forgets there ever was a morning.' },
  cold: { kind: 'bad', t: 'COLD HORIZON', txt: 'It takes one blow. The Ember cracks like an egg of glass.\nNo explosion. No scream. Just... less.\nWinters come that have names now. The kiln is a monument.\nYou keep the pieces in your pocket. They never warm again.' },
  deep: { kind: 'bad', t: 'STARLESS DEEP', txt: 'You descend too soon, too alone, too unarmored by hope.\nThe Hollow King\'s lantern-light leads somewhere that is not a place.\nSomewhere, a village waits for a hero who is not coming home.\nThe dark is patient. The dark has all the time there is.' },
  keeper: { kind: 'good', t: 'KEEPER\'S DAWN', txt: 'The Ember sinks into the kiln like a key into a lock.\nWarmth runs through the village walls like a heard heartbeat.\nThey ask you to stay. You do.\nEvery year on Emberfall eve, children gather to watch you open the kiln,\nand every year the first morning pours out gold.' },
  shared: { kind: 'good', t: 'THE SHARED DAWN', txt: 'You do not hoard the morning. You divide it.\nSilver lanterns from the Hollow King\'s hoard, kindled one by one,\ncarry small suns into every window of the world.\nNo king. No keeper. Just neighbors, and light, and no more dark to fear.' },
  unwritten: { kind: 'secret', t: 'THE UNWRITTEN MORNING', txt: 'You ask the Ember the question the Shrine taught you:\n"Who lit the first morning?"\nThe Ember opens like an eye, and shows you — not the answer —\nthe moment before. The blank page. The unwritten dawn.\nAnd quietly, kindly, it hands you the pen.\nSomewhere, a new story begins where this one ends. Perhaps yours. Perhaps better.' },
};
const END_ORDER = ['ash', 'crown', 'dark', 'cold', 'deep', 'keeper', 'shared', 'unwritten'];
function endingsFound() { return END_ORDER.filter(k => META.endings[k]).length; }

'use strict';
/* ===== village NPCs ===== */
DLG.mara = () => {
  if (G.chapter === 0) return DLG._prologue();
  if (G.chapter >= 5) return [L('Mara', 'The kiln waits. So do I. Go gently.')];
  if (got('warden_done') && !got('ch2_open')) { Game.afterBossScene('warden'); return []; }
  if (got('sovereign_done') && !got('ch3_open')) { Game.afterBossScene('sovereign'); return []; }
  if (got('deepking_done') && !got('ch4_open')) { Game.afterBossScene('deepking'); return []; }
  if (got('marshal_done') && !got('finale_open')) { Game.afterBossScene('marshal'); return []; }
  const lines = { 1: 'The Whisperwood weeps sap the color of rust. Follow the west road — and keep your blade loose.',
    2: 'East, past the crossroads. The dunes eat travelers who wander without water or nerve.',
    3: 'The Barrow mouth is north-west, in the Emberrise rocks. Torches last longer than courage.',
    4: 'The Keep gate drinks sigils. You carry one. Climb, and come back changed.',
    5: 'It is time.' };
  const a = [L('Mara', lines[G.chapter] || 'Keep walking, emberling.')];
  if (qStage('q_toll') === 1 && !G.quests.q_toll.done) a.push({ c: [
    { t: 'The bandit took my coin. (pay 20 reported)', f: () => { if (G.p.coins >= 20) { G.p.coins -= 20; } advanceQuest('q_toll'); }, go: '_close' },
    { t: 'I drove him off myself.', f: () => { addHope(1, 'the toll is gone'); completeQuest('q_toll'); questReward('q_toll'); }, go: '_close' }] });
  a.push(L('Mara', 'Rest a moment — I\'ll keep the fire.'), { do: () => saveGame(true) },
    L('Mara', '(Your journey is saved.)'));
  return a;
};
DLG._prologue = () => [
  L('Mara', 'Up. UP, emberling. The kiln is cold and the village is listening to its own teeth chatter.'),
  L('Mara', 'The Ember is dimming. Without it, Bramblebrook is one long winter away from a ledger of names.'),
  L('Mara', 'You were born the night we last fed it. Maybe that means something. Prove it does.'),
  L('Mara', 'Before you go — how do you carry yourself?'),
  { c: [
    { t: '« Vigor » — I endure. ( +16 max HP )', f: () => { F('origin', 'vigor'); Game.applyOrigin(); }, go: '_prologue2' },
    { t: '« Valor » — I strike. ( +2 ATK )', f: () => { F('origin', 'valor'); Game.applyOrigin(); }, go: '_prologue2' },
    { t: '« Wits » — I notice. ( faster, keener crits )', f: () => { F('origin', 'wits'); Game.applyOrigin(); }, go: '_prologue2' }] },
];
DLG._prologue2 = () => [
  L('Mara', 'Then take this. Your mother\'s blade. It bit raiders before you drew breath.'),
  { do: () => { G.p.ownW.push('rusty'); G.p.wpn = 'rusty'; giveItem('pot_s', 2); G.p.coins += 15; } },
  L('Mara', 'Coins for the road. Ott sells potions; Bruna hammers iron. Talk to everyone — Bramblebrook remembers its own.'),
  L('Mara', 'West lies the Whisperwood, and the Warden\'s Mound. What sleeps there has stopped sleeping gently.'),
  { do: () => { Game.chSet(1); addQuest('ch1'); }, go: '_close' },
];
DLG.rowan = () => {
  const a = [];
  if (!G.quests.q_tea && !G.quests.q_tea?.done) { }
  if (!G.quests['q_tea']) a.push(L('Rowan', 'Fever in three houses. I need Moonpetals — they hide in the tall grass of the Whisperwood.'),
    { c: [{ t: 'I\'ll gather them.', f: () => addQuest('q_tea'), go: '_close' }, { t: 'Another time.', go: '_close' }] });
  else if (G.quests['q_tea'].done) a.push(L('Rowan', 'The tea works. The village breathes easier. Thank you, emberling.'));
  else if (invCount('moonpetal') >= 3) a.push(L('Rowan', 'Moonpetals! Fresh and whole. Here — you\'ve earned this.'),
    { do: () => { takeItem('moonpetal', 3); advanceQuest('q_tea'); questReward('q_tea'); }, go: '_close' });
  else a.push(L('Rowan', 'Three Moonpetals, from tall grass in the Whisperwood. (' + invCount('moonpetal') + '/3)'));
  a.push(L('Rowan', 'Travel tip: red potions heal more than they cost, if you\'re lucky with drops.'));
  return a;
};
DLG.ott = () => [L('Ott', 'Fresh from the coast! Well... fresh-ish.'), { do: () => Game.openShop('ott'), go: '_close' }];
DLG.bruna = () => {
  const a = [L('Bruna', 'Iron remembers. So do I.')];
  if (G.shards >= 7 && got('spared_all') && !G.p.ownW.includes('ember')) {
    a.push(L('Bruna', 'Seven shards... you actually gathered the morning itself.'),
      L('Bruna', 'Then hold still. This is not a sale. This is a debt the smiths of old owed.'),
      { do: () => { G.p.ownW.push('ember'); G.p.wpn = 'ember'; SFX.play('shard'); toast('EMBEREDGE forged! (+27 ATK)', 1); } },
      L('Bruna', 'The Emberedge. It hums. Don\'t apologize to it — it likes confidence.'), { go: '_close' });
  }
  const dawnOK = G.p.ownW.includes('dawn');
  if (!dawnOK && invCount('emberstone') >= 3 && G.p.coins >= 80) a.push(L('Bruna', 'Emberstone? Real emberstone?'),
    { c: [{ t: 'Forge the Dawnforged Blade. (3 emberstone + 80c)', f: () => { takeItem('emberstone', 3); G.p.coins -= 80; G.p.ownW.push('dawn'); G.p.wpn = 'dawn'; SFX.play('lvl'); toast('DAWNFORGED BLADE forged!', 1); }, go: '_close' },
      { t: 'Not yet.', go: '_shopbruna' }] });
  a.push({ do: () => Game.openShop('bruna'), go: '_close' });
  return a;
};
DLG.pip = () => {
  if (!G.quests['q_well']) return [L('Pip', 'Mister Ott says wishes cost a coin. The well eats them and never says thanks.'),
    { c: [{ t: 'Show me the well. (quest)', f: () => { addQuest('q_well'); }, go: '_close' }, { t: 'Wells don\'t take wishes, kid.', go: '_close' }] }];
  return [L('Pip', 'Did the well answer yet? Toss REAL coins. Bronze lies.')]
    .concat(G.quests.q_well.done ? [L('Pip', 'You HEARD it. The splash counted twice!')] : []);
};
DLG.tollV = () => { const q = G.quests['q_toll'];
  if (!q) return [L('Gruff', 'Toll trouble at the crossroads. Bandit named Rocco. Pays in bruises.')]
  return [L('Gruff', 'Crossroads east. Watch the treeline.')];
};

'use strict';
/* ===== wilderness NPCs ===== */
DLG.nima = () => {
  const a = [L('Nima', 'Lake Miren took my son\'s lantern. He dropped it in the Barrow Cave — I know, I KNOW, he\'s seven and shouldn\'t spelunk. He takes after me.')];
  if (!G.quests['q_lantern']) a.push({ c: [{ t: 'I\'ll find it. (quest)', f: () => addQuest('q_lantern'), go: '_close' }, { t: 'Kids and caves...', go: '_close' }] });
  else if (G.quests['q_lantern'].done) a.push(L('Nima', 'He sleeps with it lit. So do I, some nights.'));
  else if (invCount('childs_lantern') > 0) a.push(L('Nima', 'His lantern! You found it — take this charm; my mother stitched luck into the wick.'),
    { do: () => { takeItem('childs_lantern'); advanceQuest('q_lantern'); questReward('q_lantern'); }, go: '_close' });
  else a.push(L('Nima', 'Barrow Cave, north-west mountains. Careful — it bites.'));
  a.push(L('Nima', 'See the pier? The Seagrot door under it stays dark... until someone carries a lit charm. Yours is lit.'));
  return a;
};
DLG.hesan = () => {
  const a = [L('Hesan', 'The dunes are honest. It is the sun that lies.')];
  if (!G.quests['q_remedy']) a.push(L('Hesan', 'Caravans sicken crossing the deep sand. My remedy needs 2 Red Pollen and 1 Cave Moss.'),
    { c: [{ t: 'I\'ll gather them. (quest)', f: () => addQuest('q_remedy'), go: '_close' }, { t: 'Herbs are your trade.', go: '_close' }] });
  else if (G.quests['q_remedy'].done) a.push(L('Hesan', 'The remedy holds. Take the cloak — storms owe me favors, now they owe you none.'));
  else if (invCount('pollen') >= 2 && invCount('moss') >= 1) a.push(L('Hesan', 'You found them all. Breathe — the desert noticed.'),
    { do: () => { takeItem('pollen', 2); takeItem('moss', 1); advanceQuest('q_remedy'); questReward('q_remedy'); }, go: '_close' });
  else a.push(L('Hesan', '2 Red Pollen from desert blooms, 1 Cave Moss from the Barrow. (' + invCount('pollen') + '/2 pollen, ' + invCount('moss') + '/1 moss)'));
  a.push(L('Hesan', 'Rumor for the road: the buried kings left a door of glass under the sinkhole. Doors open for the patient.'));
  return a;
};
DLG.rocco = () => {
  if (G.quests['q_toll'] && G.quests['q_toll'].done) return [L('Rocco', 'Toll\'s abolished. Boss\'s orders. ...My conscience. Shut up.')];
  if (!G.quests['q_toll']) return [L('Rocco', 'Toll\'s 20 coins, hero. Or your teeth. Crossroads tax, very legal.')]
    .concat([{ c: [
      { t: 'Pay the toll. (20c)', f: () => { if (G.p.coins >= 20) { G.p.coins -= 20; addQuest('q_toll'); advanceQuest('q_toll'); toast('The road is open.'); } else toast('You can\'t afford it.'); }, go: '_close' },
      { t: 'Refuse. (fight!)', f: () => { addQuest('q_toll'); advanceQuest('q_toll'); F('rocco_fight', 1); }, go: '_close' },
      { t: '(Hope speaks) «Your brother carried wood for Mara.»', cond: () => G.hope >= 3, f: () => { addQuest('q_toll'); advanceQuest('q_toll'); completeQuest('q_toll'); questReward('q_toll'); F('rocco_spared', 1); }, go: '_close' }] }]);
  return [L('Rocco', 'Move along, coinbag.')];
};
DLG.spirit = () => {
  if (G.quests['q_ghost'] && G.quests['q_ghost'].done) return [L('Pale Spirit', 'The truth keeps warmer than a lie. Go — morning-keeper.')];
  if (!G.quests['q_ghost']) return [L('Pale Spirit', 'I am the village\'s last spoken secret. I died mid-sentence, you see. Terribly rude.'),
    { c: [{ t: 'Finish your sentence. (quest)', f: () => addQuest('q_ghost'), go: '_spirit2' }, { t: 'Another time.', go: '_close' }] }];
  return [L('Pale Spirit', 'One word. That is all that keeps me here.')];
};
DLG._spirit2 = () => [L('Pale Spirit', 'The night the Ember was first lit, the founders made a bargain — and lied about its price.'),
  { c: [
    { t: '«The village deserves the truth.»', f: () => { F('truth_spirit', 1); completeQuest('q_ghost'); questReward('q_ghost'); }, go: '_spirit3' },
    { t: '«Let them keep their comfort.»', f: () => { addHope(1, 'mercy over truth'); completeQuest('q_ghost'); questReward('q_ghost'); }, go: '_spirit3' }] }];
DLG._spirit3 = () => [L('Pale Spirit', 'Then I am free. The kiln will remember you kindly... or honestly. Both are warm.'),
  L('Pale Spirit', 'One more gift: when the dark speaks below, listen — but answer with your own name.')];
DLG.zia = () => [L('Zia', 'Oasis west, temple south of it, Keep far north-east. The gate wardens only open for sigils.'),
  L('Zia', 'Storms spin in the dune heart. A sand cloak helps. Or don\'t go. Deserts respect absence.')];
DLG.mav = () => {
  if (got('keep_open')) return [L('Gatewarden Mav', 'The gate remembers the sigil. The Keep remembers you. Go.')];
  if (invCount('sigil') > 0) return [L('Mav', 'The Ember Sigil... so the Hollow King is ended, one way or another.'),
    { do: () => { F('keep_open', 1); G.gates.keep = 1; SFX.play('quest'); toast('The Ember Keep gate opens!', 1); Game.chSet(4); }, go: '_close' },
    L('Mav', 'Beyond the gate: sentries that do not tire. Do not be anything they can predict.')];
  return [L('Mav', 'No sigil, no gate. The Keep ward drinks the Ember\'s kind of light.')];
};
DLG.hermit = () => {
  const a = [L('Grove Hermit', 'Ah. The emberling, smelling of roads.')];
  if (G.shards >= 7 && !got('shrine_awake')) a.push(L('Grove Hermit', 'Seven shards... bring them to the Shrine when the grove is quiet.'),
    { do: () => { F('shrine_ready', 1); toast('The Shrine of Mornings will listen now.', 1); } });
  a.push(L('Grove Hermit', 'The Ember remembers being a sun. Ask it who lit the first morning — if you\'re ever allowed to ask anything.'));
  return a;
};
DLG.villager = () => { const v = U.pick(Math.random, ['Chilly, eh? The kiln\'s been coughing sparks all week.', 'They say the wood glows wrong at night now.', 'Ott waters his stock. I saw him. I SAW him.', 'The well splashes back if you thank it. Try it.']);
  return [L('Villager', v)]; };

'use strict';
/* ===== chapter beat scenes ===== */
