};
DLG.shrine = () => {
  if (G.shards >= 7 || got('shrine_awake')) return DLG._shrineGo();
  return [L('Shrine of Mornings', 'The shrine\'s star-glass is clouded. It counts your Ember Shards and finds you wanting.'),
