'use strict';
/* ===== world generation: the overworld ===== */
const MAPS = {};
function setT(m, x, y, t) { if (x >= 0 && y >= 0 && x < m.w && y < m.h) m.t[y * m.w + x] = t; }
function getT(m, x, y) { return (x < 0 || y < 0 || x >= m.w || y >= m.h) ? T.MTN : m.t[y * m.w + x]; }
function fillR(m, x0, y0, x1, y1, t) { for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) setT(m, x, y, t); }
function road(m, pts, t, w) {
  t = t === undefined ? T.PATH : t; w = w || 1;
  for (let i = 0; i < pts.length - 1; i++) {
    const [ax, ay] = pts[i], [bx, by] = pts[i + 1];
    const dx = Math.sign(bx - ax), dy = Math.sign(by - ay); let x = ax, y = ay;
    while (x !== bx || y !== by) { for (let ox = -w; ox <= w; ox++) for (let oy = -w; oy <= w; oy++) setT(m, x + ox, y + oy, t); if (x !== bx) x += dx; else if (y !== by) y += dy; else break; }
    for (let ox = -w; ox <= w; ox++) for (let oy = -w; oy <= w; oy++) setT(m, bx + ox, by + oy, t);
  }
}
function scatter(m, x0, y0, x1, y1, t, p, seed, clearR) {
  for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) {
    if (U.hash(x, y, seed) < p) { if (clearR && nearTile(m, x, y, clearR, 2)) continue; setT(m, x, y, t); }
  }
}
function nearTile(m, x, y, t, r) { for (let oy = -r; oy <= r; oy++) for (let ox = -r; ox <= r; ox++) if (getT(m, x + ox, y + oy) === t) return true; return false; }
function deco(m, key, x, y, dy) { m.decos.push({ k: key, x, y, dy: dy || 0, v: Math.floor(U.hash(x, y, 51) * 2) }); }
function tag(m, x, y, o) { m.tags[x + ',' + y] = Object.assign({ x, y }, o); }
function buildWorld() {
  const W = 220, H = 220, m = { w: W, h: H, t: new Uint8Array(W * H), decos: [], tags: {}, zones: [], name: 'The Wilds', music: 'village', dark: 0 };
  MAPS.world = m;
  // base grass + variation
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
    const n = U.fbm(x, y, 11, 3);
    setT(m, x, y, n > .62 ? T.TALL : n < .34 ? T.FLOWER : T.GRASS);
  }
  // border cliffs
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) if (x < 4 || y < 4 || x >= W - 4 || y >= H - 4) setT(m, x, y, T.CLIFF);
  // north mountains with jitter
  for (let y = 4; y < 30; y++) for (let x = 4; x < W - 4; x++) {
    const e = U.fbm(x, y, 23, 3);
    if (y < 12 + e * 16) setT(m, x, y, T.MTN); else if (y < 16 + e * 16 && U.hash(x, y, 5) < .5) setT(m, x, y, T.CLIFF);
  }
  // desert east
  for (let y = 40; y < H - 30; y++) for (let x = 138; x < W - 4; x++) {
    const e = U.fbm(x + 99, y, 31, 3);
    if (x > 140 + e * 24) setT(m, x, y, T.SAND);
    if (x > 150 && x < 206 && y > 86 && y < 118 && U.hash(x, y, 77) < .05) setT(m, x, y, T.QSAND);
  }
  // lake
  const LX = 108, LY = 152, LR = 21;
  for (let y = LY - LR - 3; y <= LY + LR + 3; y++) for (let x = LX - LR - 3; x <= LX + LR + 3; x++) {
    const d = U.dist(x, y, LX, LY), wob = U.fbm(x, y, 41, 2) * 4;
    if (d < LR - 6 + wob) setT(m, x, y, T.DEEP); else if (d < LR + wob) setT(m, x, y, T.WATER);
    else if (d < LR + 3 + wob) { if (getT(m, x, y) !== T.DEEP) setT(m, x, y, U.hash(x, y, 9) < .25 ? T.SAND : T.GRASS); }
  }
  // scatter forests west (after roads later? do scatter now; roads carve later clear them)
  for (let y = 56; y < 140; y++) for (let x = 30; x < 106; x++) {
    if (U.fbm(x, y, 17, 2) > .52 && U.hash(x, y, 3) < .75) setT(m, x, y, T.GRASS); // keep floor grassy, trees as decos
  }
  buildVillage(m);
  buildRoads(m);
  decorateWorld(m);
  placeWorldTags(m);
  buildCave1(); buildCave2(); buildKeep(); buildGrot(); buildGrove();
  buildWorldZones(m);
  return m;
}
function buildRoads(m) {
  road(m, [[108, 52], [44, 52]], T.PATH);              // west road to forest
  road(m, [[112, 56], [140, 56]], T.PATH);             // east to crossroads
  road(m, [[140, 56], [140, 30], [186, 30], [186, 44]], T.PATH); // crossroads -> keep gate
  road(m, [[140, 56], [160, 84]], T.PATH);             // to oasis
  road(m, [[160, 84], [178, 84], [178, 98]], T.PATH);  // oasis -> temple
  road(m, [[108, 52], [108, 30], [80, 30], [78, 31]], T.PATH); // north -> barrow
  road(m, [[108, 54], [108, 132]], T.PATH);            // south to lake pier
}

'use strict';
/* ===== village & world structures ===== */
function house(m, x, y, w, h, doorX) {
  fillR(m, x, y, x + w - 1, y + Math.floor(h / 2), T.ROOF);
  for (let yy = y + Math.floor(h / 2); yy <= y + h - 1; yy++) for (let xx = x; xx <= x + w - 1; xx++) setT(m, xx, yy, T.WWALL);
  setT(m, x + doorX, y + h - 1, T.DOOR);
  deco(m, 'bed', x + 1, y + Math.floor(h / 2) + 1); deco(m, 'table', x + w - 2, y + Math.floor(h / 2) + 1);
}
function buildVillage(m) {
  // plaza
  fillR(m, 100, 42, 118, 54, T.PATH);
  house(m, 104, 32, 7, 5, 3);   // Mara's hut (door at 107,36)
  house(m, 112, 32, 7, 5, 3);   // Ott's shop (door 115,36)
  house(m, 119, 39, 6, 5, 2);   // Bruna's forge (door 121,43)
  house(m, 96, 46, 6, 5, 2);    // Rowan healer (door 98,50)
  house(m, 112, 47, 6, 5, 2);   // village home (door 114,51)
  house(m, 102, 47, 5, 5, 2);   // village home (door 104,51)
  deco(m, 'kiln', 101, 40, 6); deco(m, 'well', 109, 45, 4);
  deco(m, 'anvil', 120, 44, 2); deco(m, 'furnace', 123, 41, 2);
  deco(m, 'bed', 105, 34); // inn marker inside mara hut (visual)
  // farm
  fillR(m, 94, 56, 101, 62, T.GRASS); deco(m, 'fence', 93, 56, 0); deco(m, 'fence', 93, 59, 0); deco(m, 'bush', 100, 61, 0);
  for (let i = 0; i < 5; i++) deco(m, 'flowerB', 95 + i * 2, 58, 0);
  // gravestones (cemetery west)
  for (let i = 0; i < 5; i++) { deco(m, 'grave', 87 + i * 2, 62 + (i % 2) * 2, 0); setT(m, 87 + i * 2, 62 + (i % 2) * 2, T.GRASS); }
  //NPC + tag positions (see placeWorldTags)
}
function decorateWorld(m) {
  const R = Math.random;
  // trees in forest region
  for (let y = 52; y < 142; y++) for (let x = 28; x < 108; x++) {
    const t = getT(m, x, y); if (t === T.PATH || t === T.WATER || t === T.DEEP) continue;
    const n = U.fbm(x, y, 17, 2);
    if (n > .5 && U.hash(x, y, 3) < .62) deco(m, U.hash(x, y, 8) < .3 ? 'pine' : 'tree', x, y, 10);
  }
  // warden mound clearing
  for (let y = 78; y < 98; y++) for (let x = 54; x < 74; x++) if (U.dist(x, y, 64, 88) < 9) { /* leave clearing */ 
    m.decos = m.decos.filter(d => !(d.x === x && d.y === y)); }
  // scattered rocks/flowers/bushes in grasslands
  for (let y = 40; y < 200; y += 1) for (let x = 8; x < 212; x += 1) {
    const t = getT(m, x, y);
    if (t === T.GRASS || t === T.TALL) {
      const h = U.hash(x, y, 99);
      if (h < .012) deco(m, 'rock', x, y, 6); else if (h < .018) deco(m, 'bush', x, y, 4); else if (h < .021) deco(m, 'flowerB', x, y, 0);
    } else if (t === T.SAND) {
      const h = U.hash(x, y, 101);
      if (h < .015) deco(m, 'cactus', x, y, 8); else if (h < .02) deco(m, 'rock', x, y, 6); else if (h < .022) deco(m, 'skull', x, y, 2);
    } else if (t === T.MTN && U.hash(x, y, 103) < .03) deco(m, 'rock', x, y, 6);
  }
  // lake reeds & pier
  for (let y = 128; y < 178; y++) for (let x = 84; x < 134; x++) { const t = getT(m, x, y);
    if ((t === T.WATER || t === T.DEEP) && U.hash(x, y, 55) < .12) deco(m, 'reed', x, y, 2); }
  for (let i = 0; i < 6; i++) setT(m, 108, 126 + i, T.PIER);
  deco(m, 'boat', 103, 138, 2); deco(m, 'boat', 114, 141, 2);
  // oasis pond & palms & camp
  fillR(m, 157, 82, 163, 88, T.WATER); setT(m, 160, 84, T.DEEP);
  deco(m, 'pine', 155, 80, 10); deco(m, 'pine', 165, 80, 10); deco(m, 'umbrella', 164, 86, 6);
  // temple arena rings (dune sovereign)
  for (let a = 0; a < TAU; a += .12) { const x = Math.round(178 + Math.cos(a) * 8), y = Math.round(102 + Math.sin(a) * 8); if (getT(m, x, y) !== T.PATH) setT(m, x, y, T.QSAND); }
  for (let a = 0; a < TAU; a += .2) { const x = Math.round(178 + Math.cos(a) * 12), y = Math.round(102 + Math.sin(a) * 12); deco(m, 'rock', x, y, 6); }
  deco(m, 'arch', 178, 95, 6);
  // warden mound props
  deco(m, 'stump', 60, 84, 2); deco(m, 'stump', 68, 92, 2); deco(m, 'skull', 62, 92, 2);
  // keep gate arch & campfires & signs placed in placeWorldTags
}

