function blank(w, h, wallT, floorT, name, music, dark) {
  const m = { w, h, t: new Uint8Array(w * h), decos: [], tags: {}, zones: [], name, music, dark: dark || 0 };
  m.t.fill(wallT); MAPS[name] = m; return m;
}
