'use strict';
/* ===== world renderer ===== */
Game.render = function (dt) {
  const ctx = this.ctx; ctx.setTransform(V.dpr, 0, 0, V.dpr, 0, 0);
  ctx.imageSmoothingEnabled = false;
  ctx.fillStyle = '#0b0d16'; ctx.fillRect(0, 0, V.w, V.h);
  if (G.mode === 'title' || !G.p) { Title.bg && Title.bg(ctx, dt); return; }
  const m = G.mapObj;
  const shx = (Math.random() * 2 - 1) * G.cam.shake, shy = (Math.random() * 2 - 1) * G.cam.shake;
  const cx = Math.round(G.cam.x + shx), cy = Math.round(G.cam.y + shy);
  const x0 = Math.max(0, Math.floor(cx / TILE) - 1), y0 = Math.max(0, Math.floor(cy / TILE) - 1);
  const x1 = Math.min(m.w - 1, Math.ceil((cx + V.w) / TILE) + 1), y1 = Math.min(m.h - 1, Math.ceil((cy + V.h) / TILE) + 1);
  const animF = Math.floor(G.time * 3) % 3, animF2 = Math.floor(G.time * 3) % 2;
  // tiles
  for (let ty = y0; ty <= y1; ty++) for (let tx = x0; tx <= x1; tx++) {
    const t = m.t[ty * m.w + tx]; const arr = SPR.tiles[t]; if (!arr) continue;
    const fr = SPR.anim[t] ? arr[(Math.floor(G.time * 2.5) + tx + ty) % arr.length] : arr[U.hash(tx, ty, 5) * arr.length | 0];
    ctx.drawImage(fr, tx * TILE - cx, ty * TILE - cy);
  }
  // tags: chests & special props drawn as sprites
  for (let ty = y0; ty <= y1; ty++) for (let tx = x0; tx <= x1; tx++) {
    const t = m.tags[tx + ',' + ty]; if (!t) continue;
    if (t.type === 'chest') { const op = G.opened[G.mapKey + ':' + tx + ',' + ty]; ctx.drawImage(op ? SPR.decos.chestO : SPR.decos.chest, tx * TILE - cx, ty * TILE + 2 - cy); }
    else if (t.type === 'heart') { const img = SPR.decos.emberheart[animF]; ctx.drawImage(img, tx * TILE + 8 - img.width / 2 - cx, ty * TILE + 16 - img.height - cy); }
    else if (t.type === 'shrine') { const img = SPR.decos.shrine; ctx.drawImage(img, tx * TILE + 8 - img.width / 2 - cx, ty * TILE + 16 - img.height - cy); }
    else if (t.type === 'kiln') { const img = SPR.decos.kiln; ctx.drawImage(img, tx * TILE + 8 - img.width / 2 - cx, ty * TILE + 16 - img.height - cy); }
    else if (t.type === 'well') { const img = SPR.decos.well; ctx.drawImage(img, tx * TILE + 8 - img.width / 2 - cx, ty * TILE + 16 - img.height - cy); }
  }
  // build y-sorted draw list: decos + npcs + mobs + player + drops
  const list = [];
  for (const d of m.decos) { if (d.x < x0 - 1 || d.x > x1 + 1 || d.y < y0 - 2 || d.y > y1 + 1) continue;
    const imgSet = SPR.decos[d.k]; if (!imgSet) continue; const img = imgSet[d.v % imgSet.length] || imgSet[0];
    list.push({ y: d.y * TILE + 16, draw: (i) => ctx.drawImage(i.img, d.x * TILE + 8 - i.img.width / 2 - cx, d.y * TILE + 16 - i.img.height - cy), img }); }
  for (const key in m.tags) { const t = m.tags[key]; if (t.type !== 'npc') continue;
    if (t.x < x0 - 1 || t.x > x1 + 1 || t.y < y0 - 2 || t.y > y1 + 1) continue;
    const ch = SPR.chars[t.k]; if (!ch) continue; const img = ch.down[0];
    const bob = Math.sin(G.time * 2 + t.x) > .6 ? 1 : 0;
    list.push({ y: t.y * TILE + 15, draw: (i) => ctx.drawImage(i.img, t.x * TILE + 8 - 8 - cx, t.y * TILE + 16 - i.img.height - cy + i.bob), img, bob }); }
  for (const mo of G.mobs) { if (mo.dead) continue; if (mo.x < cx - 30 || mo.x > cx + V.w + 30 || mo.y < cy - 40 || mo.y > cy + V.h + 40) continue;
    list.push({ y: mo.y, draw: (i) => this.drawMob(i.mo, cx, cy) , mo }); }
  list.push({ y: G.p.y, draw: () => this.drawPlayer(cx, cy) });
  for (const d of G.drops) list.push({ y: d.y, draw: (i) => { const s = d.kind === 'coin' ? SPR.icons.coin : SPR.icons[ITEMS[d.item] ? ITEMS[d.item].icon : 'coin'];
    ctx.drawImage(s, d.x - 5 - cx, d.y - 6 - Math.abs(Math.sin(d.t * 4)) * 3 - cy); }, });
  list.sort((a, b) => a.y - b.y);
  for (const it of list) it.draw(it);
  // projectiles & telegraphs above
  for (const pr of G.projs) { const img = SPR.projs[pr.img]; if (img) ctx.drawImage(img, pr.x - img.width / 2 - cx, pr.y - img.height / 2 - cy); }
  for (const pt of G.parts) {
    if (pt.kind === 'tele') { const pr = 1 - pt.t / pt.dur; ctx.strokeStyle = 'rgba(255,93,93,' + (.4 + pr * .5) + ')'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(pt.x - cx, pt.y - cy, pt.r, 0, TAU); ctx.stroke();
      ctx.fillStyle = 'rgba(255,93,93,' + (.08 + pr * .12) + ')'; ctx.fill(); }
    else if (pt.kind === 'ring') { ctx.strokeStyle = pt.col || '#7ee0ff'; ctx.globalAlpha = pt.t / .6; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.arc(pt.x - cx, pt.y - cy, pt.r, 0, TAU); ctx.stroke(); ctx.globalAlpha = 1; }
    else { ctx.fillStyle = pt.col; ctx.fillRect(pt.x - cx, pt.y - cy, pt.s || 2, pt.s || 2); }
  }
  // slash arc
  if (G.p.atkT > 0) {
    const fa = [1.5708, -1.5708, Math.PI, 0][G.p.atkDir];
    const prog = 1 - G.p.atkT / .18; const a = fa + (prog - .5) * 1.6;
    ctx.save(); ctx.translate(G.p.x - cx, G.p.y - 6 - cy); ctx.rotate(a);
    ctx.drawImage(SPR.sl.a, -3, -13); ctx.restore();
  }
  // floating texts
  ctx.font = '7px monospace'; ctx.textAlign = 'center';
  for (const ft of G.texts) { ctx.globalAlpha = Math.min(1, ft.t * 2); ctx.fillStyle = '#000'; ctx.fillText(ft.txt, ft.x - cx + 1, ft.y - cy + 1); ctx.fillStyle = ft.col; ctx.fillText(ft.txt, ft.x - cx, ft.y - cy); }
  ctx.globalAlpha = 1;
  // interact verb
  if (G.mode === 'play') { const f = findFocus(); if (f) { const label = VERB[f.type];
    const lx = f.x * TILE + 8 - cx, ly = f.y * TILE - 12 - cy;
    ctx.fillStyle = 'rgba(5,7,13,.8)'; const w = ctx.measureText(label).width + 8; ctx.fillRect(lx - w / 2, ly - 8, w, 11);
    ctx.fillStyle = '#ffd97a'; ctx.fillText(label, lx, ly); } }
  this.drawLight(ctx, cx, cy);
};

'use strict';
/* ===== lighting, characters, mobs draw, weather ===== */
Game.drawPlayer = function (cx, cy) {
  const p = G.p, ctx = this.ctx;
  if (p.inv > 0 && Math.floor(G.time * 18) % 2) return; // blink
  const dirN = ['down', 'up', 'left', 'right'][p.face];
  const moving = Math.abs(p.vx) + Math.abs(p.vy) > 4;
  const fr = moving ? (Math.floor(G.time * 9) % 2) : 0;
  const ch = SPR.chars.player[dirN][fr] || SPR.chars.player[dirN][0];
  ctx.drawImage(ch, Math.round(p.x - 8 - cx), Math.round(p.y - ch.height + 3 - cy));
  if (p.rollT > 0) { ctx.globalAlpha = .35; ctx.drawImage(ch, Math.round(p.x - p.vx * .03 - 8 - cx), Math.round(p.y - ch.height + 3 - cy)); ctx.globalAlpha = 1; }
  // weapon hint while attacking
  if (p.atkT > 0) { /* slash drawn separately */ }
};
Game.drawMob = function (m, cx, cy) {
  const ctx = this.ctx;
  const frames = SPR.mobs[m.def.spr]; if (!frames) return;
  let img = frames[Math.floor(m.t * 6) % frames.length];
  const flip = m.fx === -1 || (m.state === 'dash' && m.vx < 0);
  if (flip) img = img._mir || (img._mir = mirror(img));
  const dy = m.def.ai === 'flutter' ? Math.sin(m.t * 6) * 3 : 0;
  const hop = m.state === 'hop' ? -6 : 0;
  ctx.drawImage(img, Math.round(m.x - img.width / 2 - cx), Math.round(m.y - img.height + 2 - cy + dy + hop));
  if (m.flash > 0) { ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = .55; ctx.drawImage(img, Math.round(m.x - img.width / 2 - cx), Math.round(m.y - img.height + 2 - cy + dy + hop)); ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over'; }
  if (m.state === 'wind') { ctx.strokeStyle = '#ffd97a'; ctx.strokeRect(m.x - 10 - cx, m.y - img.height - 6 - cy, 20, 3); }
  // small hp bar for damaged normal mobs
  if (!m.boss && m.hp < m.maxhp) {
    ctx.fillStyle = '#05070d'; ctx.fillRect(m.x - 8 - cx, m.y - img.height - 8 - cy, 16, 3);
    ctx.fillStyle = '#ff5d5d'; ctx.fillRect(m.x - 7 - cx, m.y - img.height - 7 - cy, 14 * U.clamp(m.hp / m.maxhp, 0, 1), 1);
  }
};
Game.drawLight = function (ctx, cx, cy) {
  const m = G.mapObj; if (!this.light) return;
  let dark = m.dark || 0;
  const clock = G.clock; // minutes
  const nightA = (clock > 1230 || clock < 330) ? .5 : (clock > 1140 ? (clock - 1140) / 90 * .5 : (clock < 420 ? (420 - clock) / 90 * .5 : 0));
  const isDarkMap = dark > 0;
  if (!isDarkMap && nightA < .06) { // daylight tint only
    if (nightA > 0) { ctx.fillStyle = 'rgba(10,16,48,' + (nightA * .5) + ')'; ctx.fillRect(0, 0, V.w, V.h); }
    return;
  }
  const L = this.light, lg = this.lightCtx;
  if (L.width !== V.w || L.height !== V.h) { L.width = V.w; L.height = V.h; }
  lg.globalCompositeOperation = 'source-over';
  lg.clearRect(0, 0, V.w, V.h);
  lg.fillStyle = 'rgba(4,6,16,' + (isDarkMap ? dark : nightA) + ')';
  lg.fillRect(0, 0, V.w, V.h);
  lg.globalCompositeOperation = 'destination-out';
  const hole = (x, y, r, a) => { const g2 = lg.createRadialGradient(x, y, 2, x, y, r);
    g2.addColorStop(0, 'rgba(0,0,0,' + a + ')'); g2.addColorStop(1, 'rgba(0,0,0,0)');
    lg.fillStyle = g2; lg.beginPath(); lg.arc(x, y, r, 0, TAU); lg.fill(); };
  hole(G.p.x - cx, G.p.y - cy, 86 + Math.sin(G.time * 5) * 3, 1);
  const x0 = Math.max(0, Math.floor(cx / TILE) - 6), y0 = Math.max(0, Math.floor(cy / TILE) - 6);
  const x1 = Math.min(m.w - 1, Math.ceil((cx + V.w) / TILE) + 6), y1 = Math.min(m.h - 1, Math.ceil((cy + V.h) / TILE) + 6);
  for (let ty = y0; ty <= y1; ty++) for (let tx = x0; tx <= x1; tx++) {
    const t = m.t[ty * m.w + tx];
    if (t === T.GLOW) hole(tx * TILE + 8 - cx, ty * TILE + 8 - cy, 30, .8);
    else if (t === T.LAVA) hole(tx * TILE + 8 - cx, ty * TILE + 8 - cy, 26, .7);
    const tg = m.tags[tx + ',' + ty];
    if (tg && tg.type === 'camp') hole(tx * TILE + 8 - cx, ty * TILE + 8 - cy, 46 + Math.sin(G.time * 7 + tx) * 4, .95);
  }
  lg.globalCompositeOperation = 'source-over';
  ctx.drawImage(L, 0, 0);
  if (!isDarkMap && nightA > 0) { ctx.fillStyle = 'rgba(10,16,48,' + (nightA * .4) + ')'; ctx.fillRect(0, 0, V.w, V.h); }
};
Game.weather = function () {
  const inStorm = G.mapKey === 'world' && (() => { const x = G.p.x / TILE, y = G.p.y / TILE; return x > 168 && x < 200 && y > 86 && y < 120; })();
  const cloak = G.p.acc === 'cloak' || G.p.ownC.includes('cloak');
  $('storm').style.opacity = inStorm ? (cloak ? .25 : .85) : 0;
  if (inStorm && !cloak && Math.random() < .004) hurtPlayer(3, U.irnd(-40, 40), 0);
  if (inStorm && Math.random() < .3) G.parts.push({ kind: 'p', x: G.cam.x + Math.random() * V.w, y: G.cam.y + Math.random() * V.h, vx: -U.irnd(40, 120), vy: U.irnd(-10, 10), g: 0, t: .5, col: 'rgba(217,195,126,.4)', s: 1 });
};
/* title background embers */
Title.bg = function (ctx, dt) {
  const g = ctx.createLinearGradient(0, 0, 0, V.h);
  g.addColorStop(0, '#0b0d16'); g.addColorStop(.7, '#1a1020'); g.addColorStop(1, '#2a1420');
  ctx.fillStyle = g; ctx.fillRect(0, 0, V.w, V.h);
  this._em = this._em || [];
  if (this._em.length < 40 && Math.random() < .3) this._em.push({ x: Math.random() * V.w, y: V.h + 10, vy: -U.irnd(14, 40), vx: U.irnd(-8, 8), s: U.irnd(1, 2), t: 1 });
  for (const e of this._em) { e.y += e.vy * dt; e.x += e.vx * dt; ctx.fillStyle = 'rgba(242,176,74,' + (e.t * .8) + ')'; ctx.fillRect(e.x, e.y, e.s, e.s); }
  this._em = this._em.filter(e => e.y > -12);
  ctx.fillStyle = 'rgba(242,176,74,.05)'; ctx.fillRect(0, V.h * .8, V.w, V.h * .2);
};
Title.update = function () { };

content.text:
Note: Game.weather needs to be called in update — add call in Game.update play branch. Also Title.bg references V & dt fine.

main.js: boot everything: window.onload → Game.init(); hide #boot.

Also wire: when play starts (newGame/continue), show hud & touch (already in Title buttons). In Title.show hide hud/touch; buttons unhide. Good.

Also 'menu' button touch → Input.set('menu') edge → Game.checkMenus opens pause. In menus, touch users need buttons clickable — menus are DOM with pointer events. Fine.

Also need: when G.mode==='menu' render still draws world behind (Game.render runs; mode!=='title' → draws). update returns early — static. Good.

main.js:
```
window.addEventListener('load', () => {
  Game.init();
  $('boot').classList.add('hidden'); $('boot').classList.remove('shown');
});
```
Also prevent context menu & touch gestures:
document.addEventListener('contextmenu', e=>e.preventDefault());
document.addEventListener('touchmove', e=>e.preventDefault(), {passive:false})? touch-action none handles.

Also add weather call: edit game_core update to call this.weather() in play mode. Add now via edit. Then main.js. Then run node --check on all files.

