/* headless smoke test for EMBERFALL */
const fs = require('fs'), path = require('path'), vm = require('vm');
const ROOT = '/home/runner/work/My2w/My2w/emberfall';
let errors = [];
function makeCtx() {
  const grad = { addColorStop() { } };
  const target = {};
  return new Proxy(target, {
    get(t, k) {
      if (k === 'createLinearGradient' || k === 'createRadialGradient' || k === 'createPattern') return () => grad;
      if (k === 'measureText') return () => ({ width: 12 });
      if (k === 'getImageData') return () => ({ data: new Uint8ClampedArray(4) });
      if (k in t) return t[k];
      return () => undefined;
    },
    set(t, k, v) { t[k] = v; return true; },
  });
}
function makeEl(tag) {
  const e = {
    tag, style: {}, children: [], _cls: new Set(),
    classList: { add(...c) { c.forEach(x => e._cls.add(x)); }, remove(...c) { c.forEach(x => e._cls.delete(x)); }, toggle() { }, contains(c) { return e._cls.has(c); } },
    appendChild(c) { e.children.push(c); return c; },
    removeChild(c) { const i = e.children.indexOf(c); if (i >= 0) e.children.splice(i, 1); return c; },
    remove() { },
    setAttribute() { }, getAttribute() { return null; },
    addEventListener() { }, setPointerCapture() { },
    getContext() { if (!e._ctx) e._ctx = makeCtx(); return e._ctx; },
    get firstChild() { return e.children[0]; },
    get firstElementChild() { if (!e._sub) e._sub = makeEl('sub'); return e._sub; },
    width: 0, height: 0,
  };
  e.onclick = null; e.onpointerdown = null; e.onmouseenter = null;
  return e;
}
const els = {};
const sandbox = {
  console, Math, JSON, Object, Array, Uint8Array, Uint8ClampedArray, String, Number, Boolean, Date, RegExp, Error, parseInt, parseFloat, isNaN, isFinite,
  setTimeout, clearTimeout, setInterval, clearInterval, btoa: s => Buffer.from(s, 'binary').toString('base64'), atob: s => Buffer.from(s, 'base64').toString('binary'),
  document: {
    getElementById: id => els[id] || (els[id] = makeEl('div#' + id)),
    createElement: tag => makeEl(tag),
    body: makeEl('body'), addEventListener() { }, hidden: false,
  },
  navigator: { maxTouchPoints: 0, vibrate() { } },
  localStorage: (() => { const m = {}; return { getItem: k => (k in m ? m[k] : null), setItem: (k, v) => { m[k] = String(v); }, removeItem: k => { delete m[k]; } }; })(),
  requestAnimationFrame(cb) { sandbox.__raf.push(cb); return sandbox.__raf.length; },
  performance: { now: () => Date.now() },
};
sandbox.window = sandbox; sandbox.globalThis = sandbox;
sandbox.__raf = [];
sandbox.window.addEventListener = () => { };
sandbox.window.innerWidth = 1280; sandbox.window.innerHeight = 720; sandbox.window.devicePixelRatio = 1;
vm.createContext(sandbox);
const files = ['core', 'save', 'audio', 'input', 'sprites_core', 'sprites_tiles', 'sprites_decos', 'sprites_chars', 'sprites_mobs', 'sprites_icons', 'items', 'mobs_data', 'story_core', 'dlg_village', 'dlg_world', 'dlg_story', 'dlg_boss', 'dlg_final', 'worldgen', 'world_village', 'world_tags', 'world_caves', 'world_keep', 'ent_core', 'ent_mobs', 'ent_fx', 'boss', 'game_core', 'game_flow', 'game_dialog', 'game_ui', 'game_menus', 'game_render', 'game_render2', 'main'];
for (const f of files) {
  const code = fs.readFileSync(path.join(ROOT, 'js', f + '.js'), 'utf8');
  try { vm.runInContext(code, sandbox, { filename: f + '.js' }); } catch (e) { errors.push('LOAD ' + f + ': ' + e.stack); }
}
function step(code) { try { return vm.runInContext(code, sandbox, { filename: 'step' }); } catch (e) { errors.push('STEP: ' + e.stack); } }
function pump(n, ms) { for (let i = 0; i < n; i++) { const cbs = sandbox.__raf.splice(0); if (!cbs.length) break; for (const cb of cbs) { try { cb((sandbox.__t = (sandbox.__t || 0) + (ms || 16.7))); } catch (e) { errors.push('FRAME: ' + e.stack); } } } }
function fastForwardDlg(max) {
  let n = 0;
  while (vm.runInContext('G.mode', sandbox) === 'dialog' && n++ < (max || 300)) {
    const hasCh = vm.runInContext('!!Dlg._ch', sandbox);
    if (hasCh) step('Dlg.pick(0)');
    else step('Dlg.typing=false; Dlg.next()');
  }
}
console.log('--- boot ---');
step('Game.init()');
pump(5);
console.log('mode:', step('G.mode'));
console.log('--- new game ---');
step('Game.newGame()');
fastForwardDlg();
console.log('after prologue: chapter', step('G.chapter'), 'mode', step('G.mode'), 'hp', step('G.p.hp'), 'maxhp', step('G.p.maxhp'));
console.log('--- walk & fight ---');
step('Input.down.right=true; Input.down.down=true');
pump(240);
step('Input.down.right=false; Input.down.down=false; Input.down.Space=true');
pump(3); step('Input.down.Space=false');
pump(30);
console.log('pos', step('[G.p.x|0, G.p.y|0]'), 'mobs', step('G.mobs.length'), 'parts', step('G.parts.length'));
console.log('--- maps tour ---');
for (const mk of ['world', 'cave1', 'cave2', 'keep', 'grot', 'grove']) {
  step('Game.goto("' + mk + '", 60, 60, 0, true)'); pump(30);
  console.log(mk, 'mobs', step('G.mobs.length'), 'ok');
}
console.log('--- bosses ---');
step('G.chapter=1; Game.goto("world", 64*16, 88*16, 0, true)');
pump(10);
step('Game.tryBoss({type:"boss",boss:"warden",x:64,y:88})');
fastForwardDlg();
pump(10);
console.log('warden spawned:', step('!!G.boss'));
step('if(G.boss){G.boss.hp=1; hurtMob(G.boss)}');
pump(30); // wait 900ms
fastForwardDlg();
pump(10);
console.log('after warden: spared', step('got("spared_warden")'), 'ch', step('G.chapter'));
const bosses = [['sovereign', 2, 178, 102, 'world'], ['deepking', 3, 20, 31, 'cave2'], ['marshal', 4, 20, 5, 'keep']];
for (const [b, ch, x, y, map] of bosses) {
  step('G.chapter=' + ch + '; delete G.triggers["' + b + '_intro"]; Game.goto("' + map + '", ' + x + '*16, ' + (y + 2) + '*16, 0, true)');
  pump(10);
  step('Game.tryBoss({type:"boss",boss:"' + b + '",x:' + x + ',y:' + y + '})');
  fastForwardDlg(); pump(10);
  step('if(G.boss){G.boss.hp=1; hurtMob(G.boss)}');
  pump(30); fastForwardDlg(); pump(20);
  console.log(b, 'spared:', step('got("spared_' + b + '")'), 'ch', step('G.chapter'), 'mode', step('G.mode'));
}
console.log('--- finale ---');
step('F("finale_at",0); Dlg.runArray(DLG.finale_enter().concat([{go:"finale"}]))');
fastForwardDlg();
const chIdx = step('Dlg._ch ? Dlg._ch.findIndex(c=>c.t.includes("kiln")) : -1');
console.log('finale choices:', step('Dlg._ch && Dlg._ch.map(c=>c.t.slice(0,30))'));
step('Dlg.pick(' + (chIdx >= 0 ? chIdx : 0) + ')');
pump(10);
console.log('ending mode:', step('G.mode'), 'endings found:', step('endingsFound()'));
console.log('--- save/load ---');
step('G.mode="play"; saveGame(true)');
console.log('load ok:', step('loadInto()'));
console.log('--- shops & menus ---');
step('Menus.shop("ott")'); step('Menus.close()');
step('Menus.open("inv")'); step('Menus.render()'); step('Menus.close()');
step('Menus.open("map")'); step('Menus.close()');
step('Menus.open("quests")'); step('Menus.close()');
console.log('--- render smoke (world + caves) ---');
for (const mk of ['world', 'cave2', 'keep', 'grove']) { step('Game.goto("' + mk + '", 60, 60, 0, true)'); pump(6); }
console.log('--- done. errors: ' + errors.length + ' ---');
for (const e of errors.slice(0, 14)) console.log('\n' + e.split('\n').slice(0, 6).join('\n'));

