const base = require('fs').readFileSync('/tmp/opencode/run2.js', 'utf8');
const head = base.split('const arg=process.argv[2];')[0];
const tail = `
try{ vm.runInContext('Game.init()',sandbox,{filename:'init'}); }catch(e){ console.log('init err',e.message); }
const out = vm.runInContext(\`
(() => {
  const missing = {}, empty = {}, variant = {};
  for (const k in MAPS) { const m = MAPS[k];
    for (const d of m.decos) {
      const s = SPR.decos[d.k];
      if (!s) missing[d.k] = (missing[d.k]||0)+1;
      else if (!s.length) empty[d.k] = (empty[d.k]||0)+1;
      else if (d.v >= s.length) variant[d.k] = (variant[d.k]||0)+1;
    }
    for (const key in m.tags) { const t = m.tags[key];
      if (t.type==='npc' && !SPR.chars[t.k]) missing['char:'+t.k] = 1;
    }
    for (const key in SPR.anim) if (!SPR.tiles[key] || !SPR.tiles[key].length) missing['animTile:'+key]=1;
  }
  return JSON.stringify({missing, empty, variant});
})()
\`, sandbox);
console.log(out);
const out2 = vm.runInContext('JSON.stringify(Object.keys(SPR.decos))', sandbox);
console.log('built decos:', out2);
`;
require('fs').writeFileSync('/tmp/opencode/audit.js', head + tail);
console.log('ok');

